it('política é capturada uma vez na comparação pronta', () => {
  let lengthReads = 0;
  let digitReads = 0;
  const limits = {
    get maxInputLength() {
      lengthReads += 1;
      return lengthReads === 1 ? 256 : 0;
    },
    get maxDigits() {
      digitReads += 1;
      return digitReads === 1 ? 64 : 0;
    }
  };
  const result = calculateFinancialMarginTarget(baseInput(), limits);
  if (result.status !== 'conditional') throw Error(result.reason);
  expect(lengthReads).toBe(1);
  expect(digitReads).toBe(1);
  expect(Object.isFrozen(limits)).toBe(false);
  const assessment = readyAssessment(result.value.assessment);
  expect(assessment.meta).toBe(50);
  expect(assessment.ratio.numerator).toBe('1');
  expect(assessment.ratio.denominator).toBe('2');
  expect(assessment.slack.numerator).toBe('1');
  expect(assessment.slack.denominator).toBe('100');
  expect(assessment.reachesModeledMargin).toBe(true);
  expect(result.value.assessment).toBe(assessment);
  expect(result.projection.value.netProfit.numerator).toBe('510');
  expect(result.projection.value.netProfit.denominator).toBe('1');
});

it('política é capturada uma vez também na falha técnica', () => {
  let lengthReads = 0;
  let digitReads = 0;
  const limits = {
    get maxInputLength() {
      lengthReads += 1;
      return lengthReads === 1 ? 256 : 0;
    },
    get maxDigits() {
      digitReads += 1;
      return digitReads === 1 ? 64 : 0;
    }
  };
  const result = calculateFinancialMarginTarget({
    ...baseInput(),
    requiredMarginPercent: r('1'.repeat(65))
  }, limits);
  expect(lengthReads).toBe(1);
  expect(digitReads).toBe(1);
  expect(Object.isFrozen(limits)).toBe(false);
  if (result.status !== 'unavailable') throw Error(result.reason);
  expect(result.code).toBe('calculation-unavailable');
  expect(result.projection).not.toBeNull();
  const projection = result.projection as Extract<FinancialProjectionResult, {status: 'ready'}>;
  expect(projection.value.netProfit.numerator).toBe('510');
  expect(projection.value.netProfit.denominator).toBe('1');
  expect(result.calculation).not.toBeNull();
  expect(result.reason).not.toBe('');
  expect(result).not.toHaveProperty('value');
});
